import React from 'react';
import { Routes, Route, Navigate } from 'react-router-dom';
import { useAuth } from './hooks/useAuth';

import AdminLogin from './components/pages/AdminLogin';
import AdminDashboard from './components/pages/AdminDashboard';
import AdminEvents from './components/pages/AdminEvents';
import AdminGallery from './components/pages/AdminGallery';
import AdminVideos from './components/pages/AdminVideos';
import AdminServices from './components/pages/AdminServices';
import AdminCourses from './components/pages/AdminCourses';
import AdminMessages from './components/pages/AdminMessages';
import AdminSettings from './components/pages/AdminSettings';
import AdminTestimonials from './components/pages/AdminTestimonials';
import AdminSchools from './components/pages/AdminSchools';
import AdminLeadership from './components/pages/AdminLeadership';

import AdminLayout from './components/layout/AdminLayout';


const PrivateRoute = ({ children }) => {
  const { isAuthenticated, loading } = useAuth();

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-blue-900"></div>
      </div>
    );
  }

  return isAuthenticated
    ? children
    : <Navigate to="/login" replace />;
};


function App() {
  return (
    <Routes>

      {/* ==========================================
          LOGIN
      ========================================== */}
      <Route
        path="/login"
        element={<AdminLogin />}
      />


      {/* ==========================================
          ADMIN PRIVATE ROUTES
      ========================================== */}
      <Route
        path="/*"
        element={
          <PrivateRoute>
            <AdminLayout>

              <Routes>

                {/* Dashboard */}
                <Route
                  path="/"
                  element={<AdminDashboard />}
                />

                {/* Events */}
                <Route
                  path="events"
                  element={<AdminEvents />}
                />

                {/* Gallery */}
                <Route
                  path="gallery"
                  element={<AdminGallery />}
                />

                {/* Videos */}
                <Route
                  path="videos"
                  element={<AdminVideos />}
                />

                {/* Services */}
                <Route
                  path="services"
                  element={<AdminServices />}
                />

                {/* Courses */}
                <Route
                  path="courses"
                  element={<AdminCourses />}
                />

                {/* Schools */}
                <Route
                  path="schools"
                  element={<AdminSchools />}
                />

                {/* Leadership Team */}
                <Route
                  path="leadership"
                  element={<AdminLeadership />}
                />

                {/* Testimonials */}
                <Route
                  path="testimonials"
                  element={<AdminTestimonials />}
                />

                {/* Messages */}
                <Route
                  path="messages"
                  element={<AdminMessages />}
                />

                {/* Settings */}
                <Route
                  path="settings"
                  element={<AdminSettings />}
                />

              </Routes>

            </AdminLayout>
          </PrivateRoute>
        }
      />

    </Routes>
  );
}

export default App;
